import argparse,json,csv,sys
from pathlib import Path
ap=argparse.ArgumentParser();ap.add_argument('--run',required=True);ap.add_argument('--split',required=True,choices=['development','reserved']);a=ap.parse_args();R=Path(__file__).resolve().parents[1];run=Path(a.run);sp={x['canonical_id']:x['split'].lower() for x in csv.DictReader(open(R/'data/split_manifest_v0_5.csv'))};expected={x['call_id'] for x in map(json.loads,open(R/'prompts/model_calls_v0_5.jsonl')) if sp[x['canonical_id']]==a.split};reg=[json.loads(x) for x in open(run/'call_registry.jsonl')];ids=[x['call_id'] for x in reg];scores={x['call_id'] for x in map(json.loads,open(run/'scoring_records.jsonl'))} if (run/'scoring_records.jsonl').exists() else set();checks={'expected_all_terminal':set(ids)==expected,'no_duplicate_terminal':len(ids)==len(set(ids)),'every_completed_has_score':all(x['call_id'] in scores for x in reg if x['terminal_status'].startswith('COMPLETED')),'manifest_present':(run/'run_manifest.json').exists()};out={'status':'PASS' if all(checks.values()) else 'FAIL','checks':checks,'expected':len(expected),'terminal':len(ids)};json.dump(out,open(run/'run_completion_report.json','w'),indent=2);print(json.dumps(out,indent=2));sys.exit(0 if out['status']=='PASS' else 1)
